//! Byte-exact Rust port of `test19.cpp`.
//!
//! The original is a small C++ program that drives three helpers from a
//! (missing) `indicators.hpp` header: [`CyclicProgress`], [`ProgressDisplay`]
//! and [`Format`]. Their behaviour was recovered black-box from the shipped
//! binary `test19_executable`; see the `indicators` module for the details.
//!
//! This file mirrors the C++ `main` line for line, including the fact that
//! `main` accepts `(argc, argv)` and never looks at them.

mod indicators;

use indicators::{CyclicProgress, Format, ProgressDisplay};

fn main() {
    // C++: `int main(int argc, char* argv[])`.
    //
    // The arguments are received and then deliberately ignored -- the original
    // `main` never reads `argc` or `argv`, so this program's stdout is
    // invariant under any command line. We still bind them (and never index,
    // parse or unwrap anything) so the shape of the C++ entry point survives
    // and no argument can ever cause a panic.
    let argv: Vec<String> = std::env::args().collect();
    let _argc = argv.len();
    let _ = &argv;

    // --- Spinners ------------------------------------------------------
    let mut cyclic1 = CyclicProgress::new(5);
    let mut cyclic2 = CyclicProgress::new(10);
    let mut cyclic3 = CyclicProgress::new(15);

    for _i in 0..3 {
        cyclic1.next();
    }
    for _i in 0..6 {
        cyclic2.next();
    }
    for _i in 0..9 {
        cyclic3.next();
    }

    println!("{}", cyclic1.str());
    println!("{}", cyclic2.str());
    println!("{}", cyclic3.str());

    // --- Progress displays ---------------------------------------------
    // C++: `indicators::ProgressDisplay displays[3];` default-constructs the
    // array, then each slot is overwritten by assignment.
    let mut displays: [ProgressDisplay; 3] = Default::default();
    displays[0] = ProgressDisplay::new(50);
    displays[1] = ProgressDisplay::new(100);
    displays[2] = ProgressDisplay::new(200);

    displays[0].update(25);
    displays[1].update(75);
    displays[2].update(150);

    for i in 0..3 {
        println!("{}", displays[i].display());
    }

    displays[0].increment(5);
    displays[1].increment(10);
    displays[2].increment(20);

    for i in 0..3 {
        println!("{}", displays[i].display());
    }

    // --- Free-standing formatters ---------------------------------------
    // `Format::percentage(0.25f)` relies on the C++ default argument
    // `precision = 1`; Rust has no default arguments, so the defaulted form is
    // a separate associated function.
    println!("{}", Format::percentage(0.25f32));
    println!("{}", Format::percentage_with(0.5f32, 2));
    println!("{}", Format::percentage_with(0.75f32, 3));
    println!("{}", Format::progress(25, 100));
    println!("{}", Format::progress(50, 100));
    println!("{}", Format::progress(75, 100));

    // C++: `return 0;`
}

#[cfg(test)]
mod tests {
    use super::indicators::{CyclicProgress, Format, ProgressDisplay};

    /// The complete expected stdout of `test19_executable`, byte for byte.
    /// Captured with `od -c`; the three spinner glyphs are U+28BF, U+28EF and
    /// U+28FD (frame indices 3, 6 and 1).
    const EXPECTED: &str = concat!(
        "\u{28BF} 60.0%\n",
        "\u{28EF} 60.0%\n",
        "\u{28FD} 60.0%\n",
        "Progress: 50.0% (25/50)\n",
        "Progress: 75.0% (75/100)\n",
        "Progress: 75.0% (150/200)\n",
        "Progress: 60.0% (30/50)\n",
        "Progress: 85.0% (85/100)\n",
        "Progress: 85.0% (170/200)\n",
        "25.0%\n",
        "50.00%\n",
        "75.000%\n",
        "25/100\n",
        "50/100\n",
        "75/100\n",
    );

    /// Re-runs the exact body of `main` into a string instead of stdout.
    fn render() -> String {
        let mut out = String::new();

        let mut cyclic1 = CyclicProgress::new(5);
        let mut cyclic2 = CyclicProgress::new(10);
        let mut cyclic3 = CyclicProgress::new(15);
        for _ in 0..3 {
            cyclic1.next();
        }
        for _ in 0..6 {
            cyclic2.next();
        }
        for _ in 0..9 {
            cyclic3.next();
        }
        out.push_str(&format!("{}\n", cyclic1.str()));
        out.push_str(&format!("{}\n", cyclic2.str()));
        out.push_str(&format!("{}\n", cyclic3.str()));

        let mut displays: [ProgressDisplay; 3] = Default::default();
        displays[0] = ProgressDisplay::new(50);
        displays[1] = ProgressDisplay::new(100);
        displays[2] = ProgressDisplay::new(200);
        displays[0].update(25);
        displays[1].update(75);
        displays[2].update(150);
        for i in 0..3 {
            out.push_str(&format!("{}\n", displays[i].display()));
        }
        displays[0].increment(5);
        displays[1].increment(10);
        displays[2].increment(20);
        for i in 0..3 {
            out.push_str(&format!("{}\n", displays[i].display()));
        }

        out.push_str(&format!("{}\n", Format::percentage(0.25f32)));
        out.push_str(&format!("{}\n", Format::percentage_with(0.5f32, 2)));
        out.push_str(&format!("{}\n", Format::percentage_with(0.75f32, 3)));
        out.push_str(&format!("{}\n", Format::progress(25, 100)));
        out.push_str(&format!("{}\n", Format::progress(50, 100)));
        out.push_str(&format!("{}\n", Format::progress(75, 100)));

        out
    }

    #[test]
    fn whole_program_output_is_byte_exact() {
        assert_eq!(render(), EXPECTED);
    }

    #[test]
    fn output_byte_length_matches_the_binary() {
        // `od -c` of the reference binary ends at offset 0000336 (octal) = 222.
        assert_eq!(render().len(), 0o336);
    }

    #[test]
    fn spinner_glyph_bytes_match_the_binary_string_table() {
        // Line 1 of the reference output starts with 342 242 277 (octal).
        assert_eq!(&render().as_bytes()[..3], &[0xE2, 0xA2, 0xBF]);
    }
}

//! `indicators` -- a std-only reimplementation of the three helpers that the
//! original `test19.cpp` pulled in from `../include/indicators.hpp`.
//!
//! The header itself is not available; every rule encoded here was recovered
//! black-box from the reference binary (disassembly of the constructor,
//! `CyclicProgress::str`, `ProgressDisplay::display`, `Format::percentage` and
//! `Format::progress`, plus live probing of those symbols). Each module
//! documents the observations that pin its behaviour.
//!
//! Three cross-cutting invariants hold throughout:
//!
//! * All counters are C++ `int`, i.e. [`i32`], and nothing is ever clamped,
//!   saturated or validated.
//! * Every percentage is computed in **single precision** (`f32`) and only
//!   widened to `f64` for printing, mirroring the `divss` / `mulss` /
//!   `cvtss2sd` sequence the compiler emitted.
//! * Numbers are rendered exactly like `std::fixed << std::setprecision(n)`,
//!   which is glibc's `%.*f`. See [`cfmt`].

pub mod cfmt;
pub mod cyclic;
pub mod display;
pub mod format;

pub use cyclic::CyclicProgress;
pub use display::ProgressDisplay;
pub use format::Format;

//! C++ iostream / glibc compatible fixed-point number formatting.
//!
//! All three `indicators` types print their percentage through
//! `oss << std::fixed << std::setprecision(n) << value`, which libstdc++
//! forwards to glibc as `snprintf("%.*f", n, value)`. Rust's `{:.n$}` already
//! agrees with `%.*f` on every finite value -- both round the *exact* binary
//! value with ties-to-even -- so the only work this module does is patch up
//! the two places where the spellings differ:
//!
//! * NaN: glibc writes `nan` / `-nan` (honouring the sign bit), Rust writes
//!   `NaN` with no sign.
//! * A negative precision reaches `snprintf` through the `*` conversion, which
//!   C defines as "precision omitted", so `%f` falls back to its default of 6.
//!   `std::setprecision` stores the value sign-extended and does not clamp it.
//!
//! Infinities (`inf` / `-inf`), negative zero (`-0.0`) and subnormals already
//! match Rust's formatter with no special casing.
//!
//! Do **not** replace this with `(x * 10f64.powi(n)).round() / ...`: that is
//! ties-away-from-zero and would print `1%` where the C++ prints `0%` for
//! `0.005f`.

/// glibc's default precision for `%f` when the precision is omitted.
const DEFAULT_PRECISION: i32 = 6;

/// Formats `value` the way `std::fixed << std::setprecision(precision)` does.
///
/// `precision` is a C++ `int`; negative values behave like an omitted
/// precision (six decimals), matching `snprintf("%.*f", negative, v)`.
///
/// ```text
/// fixed(60.0,  1) == "60.0"
/// fixed(50.0,  2) == "50.00"
/// fixed( 0.5,  0) == "0"        // ties-to-even, not "1"
/// fixed(25.0, -1) == "25.000000"
/// ```
pub fn fixed(value: f64, precision: i32) -> String {
    let p = if precision < 0 {
        DEFAULT_PRECISION as usize
    } else {
        precision as usize
    };

    if value.is_nan() {
        // x86-64 produces the default QNaN 0xFFC00000 for 0.0/0.0, whose sign
        // bit is set, so `0/0` percentages print as `-nan` in the C++ binary.
        // Rust's own NaN formatting is `NaN` and drops the sign entirely.
        if value.is_sign_negative() {
            return String::from("-nan");
        }
        return String::from("nan");
    }

    // Finite and infinite values agree byte-for-byte with glibc.
    format!("{:.*}", p, value)
}

/// Widens an `f32` to `f64` exactly as `operator<<(double)` does (`cvtss2sd`)
/// and formats it with [`fixed`].
///
/// The widening is value-exact, so it can never change a digit; it exists to
/// document the C++ promotion rather than to alter the result.
pub fn fixed_f32(value: f32, precision: i32) -> String {
    fixed(value as f64, precision)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_three_precisions_used_by_the_program() {
        assert_eq!(fixed(60.0, 1), "60.0");
        assert_eq!(fixed(25.0, 1), "25.0");
        assert_eq!(fixed(50.0, 2), "50.00");
        assert_eq!(fixed(75.0, 3), "75.000");
    }

    #[test]
    fn precision_zero_omits_the_radix_point() {
        assert_eq!(fixed(25.0, 0), "25");
        assert_eq!(fixed(200.0, 0), "200");
    }

    #[test]
    fn ties_round_half_to_even_like_glibc() {
        // glibc `%.0f`: 0 2 2 4 -- NOT 1 2 3 4.
        assert_eq!(fixed(0.5, 0), "0");
        assert_eq!(fixed(1.5, 0), "2");
        assert_eq!(fixed(2.5, 0), "2");
        assert_eq!(fixed(3.5, 0), "4");
        // Exact binary ties at one decimal.
        assert_eq!(fixed(6.25, 1), "6.2");
        assert_eq!(fixed(18.75, 1), "18.8");
        assert_eq!(fixed(3.25, 1), "3.2");
    }

    #[test]
    fn negative_precision_falls_back_to_six_decimals() {
        assert_eq!(fixed(25.0, -1), "25.000000");
        assert_eq!(fixed(25.0, -3), "25.000000");
        assert_eq!(fixed(25.0, 6), "25.000000");
    }

    #[test]
    fn non_finite_spellings_match_glibc_not_rust() {
        assert_eq!(fixed(f64::INFINITY, 1), "inf");
        assert_eq!(fixed(f64::NEG_INFINITY, 1), "-inf");
        // The x86 default QNaN has its sign bit set.
        assert_eq!(fixed(0.0f32 as f64 / 0.0f32 as f64, 1), "-nan");
        assert_eq!(fixed(f64::from_bits(0x7ff8_0000_0000_0000), 1), "nan");
    }

    #[test]
    fn negative_zero_keeps_its_sign() {
        assert_eq!(fixed(-0.0, 1), "-0.0");
    }

    #[test]
    fn f32_widening_is_value_exact() {
        assert_eq!(fixed_f32(0.25f32 * 100.0f32, 1), "25.0");
        // 0.1275f32 * 100.0f32 is exactly 12.75 -> ties-to-even -> 12.8.
        assert_eq!(fixed_f32(0.1275f32 * 100.0f32, 1), "12.8");
    }
}

//! [`CyclicProgress`] -- an eight-frame braille spinner with a percentage.

use super::cfmt;

/// The spinner frame table, in the order the constructor builds it.
///
/// These are the exact bytes of the string table found in the reference
/// binary. Note that index 3 is **U+28BF** (`E2 A2 BF`), not U+283F -- the
/// latter's UTF-8 encoding does not occur anywhere in the binary, and the
/// program's own first output line begins with `E2 A2 BF`.
///
/// | # | codepoint | UTF-8      | glyph |
/// |---|-----------|------------|-------|
/// | 0 | U+28FE    | `E2 A3 BE` | ⣾     |
/// | 1 | U+28FD    | `E2 A3 BD` | ⣽     |
/// | 2 | U+28FB    | `E2 A3 BB` | ⣻     |
/// | 3 | U+28BF    | `E2 A2 BF` | ⢿     |
/// | 4 | U+287F    | `E2 A1 BF` | ⡿     |
/// | 5 | U+28DF    | `E2 A3 9F` | ⣟     |
/// | 6 | U+28EF    | `E2 A3 AF` | ⣯     |
/// | 7 | U+28F7    | `E2 A3 B7` | ⣷     |
pub const FRAMES: [&str; 8] = [
    "\u{28FE}", "\u{28FD}", "\u{28FB}", "\u{28BF}", "\u{287F}", "\u{28DF}", "\u{28EF}", "\u{28F7}",
];

/// A cyclic (never-completing) spinner.
///
/// C++ layout: `int count_` at offset 0 (initialised to 0), `int total_` at
/// offset 4 (the constructor argument), and a
/// `std::vector<std::string> frames_` holding [`FRAMES`]. The vector is an
/// implementation detail, so this port refers to the static table instead.
///
/// The constructor performs **no** validation of `total`: no zero check, no
/// sign check, no clamping.
///
/// # Quirks faithfully preserved
///
/// * [`next`](Self::next) reduces modulo `total`, so for `total > 0` the count
///   is confined to `0..total` and the percentage can never reach 100.0%.
///   `CyclicProgress::new(5)` cycles `1, 2, 3, 4, 0, 1, ...` and tops out at
///   `⡿ 80.0%`.
/// * `total == 1` therefore pins the count at 0 forever: the spinner never
///   animates and always reports `⣾ 0.0%`.
/// * A negative `total` yields the same non-negative count cycle as its
///   absolute value (C++ `%` truncates toward zero, and so does Rust's), while
///   the reported percentage is negative.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct CyclicProgress {
    /// C++ `count_`, object offset 0.
    count: i32,
    /// C++ `total_`, object offset 4. Never mutated after construction.
    total: i32,
}

impl CyclicProgress {
    /// C++: `CyclicProgress(int total) : count_(0), total_(total), frames_{...}`
    #[must_use]
    pub const fn new(total: i32) -> Self {
        Self { count: 0, total }
    }

    /// C++: `void next() { count_ = (count_ + 1) % total_; }`
    ///
    /// This is a signed, truncating modulo -- **not** a bare increment and not
    /// a clamp. The compiler emitted `add $1` followed by `cltd; idiv` with no
    /// comparison or conditional move anywhere in sight.
    ///
    /// `wrapping_add` mirrors the plain `add` instruction the C++ compiles to
    /// at `count == i32::MAX` (where C++ signed overflow is formally undefined
    /// but observably wraps), so this never panics on overflow.
    ///
    /// # Panics
    ///
    /// If `total == 0`, or on the `i32::MIN % -1` overflow pair. Both mirror
    /// the `idiv` `SIGFPE` that the C++ binary dies with on the same inputs
    /// (verified: exit status 136, "Floating point exception"); guarding them
    /// would invent behaviour the original does not have. Neither is reachable
    /// from this program, which only ever uses totals 5, 10 and 15.
    pub fn next(&mut self) {
        self.count = self.count.wrapping_add(1) % self.total;
    }

    /// The current count. C++ `count_`.
    #[must_use]
    pub const fn count(&self) -> i32 {
        self.count
    }

    /// The configured total. C++ `total_`.
    #[must_use]
    pub const fn total(&self) -> i32 {
        self.total
    }

    /// C++: `frames_[count_ % frames_.size()]`.
    ///
    /// The C++ expression converts the `int` to `size_t` (sign-extend) and then
    /// takes an *unsigned* remainder -- the binary literally does
    /// `movslq (%rbx),%rax; xor %edx,%edx; div %rcx`. Since 2^64 is a multiple
    /// of 8, that is exactly `count.rem_euclid(8)`, which is used here because
    /// it cannot produce a negative index and so cannot panic. A count of `-1`
    /// selects frame 7, not a negative slot.
    #[must_use]
    pub fn frame(&self) -> &'static str {
        FRAMES[self.count.rem_euclid(FRAMES.len() as i32) as usize]
    }

    /// C++: `static_cast<float>(count_) / total_ * 100.0f`.
    ///
    /// The arithmetic is entirely single precision (`cvtsi2ss`, `cvtsi2ss`,
    /// `divss`, `mulss` against the 4-byte constant `100.0f`); it is only
    /// widened to `double` when handed to the stream. Computing in `f64`
    /// instead produces observably different digits for reachable inputs --
    /// e.g. `count = 23, total = 80` prints `28.8` here but `28.7` in `f64`.
    #[must_use]
    pub fn percent(&self) -> f32 {
        self.count as f32 / self.total as f32 * 100.0f32
    }

    /// C++: `std::string str() const`.
    ///
    /// Emits exactly four pieces -- the frame glyph, one ASCII space, the
    /// percentage under `std::fixed << std::setprecision(1)`, and one `%`. No
    /// padding, no width, no trailing newline (the caller's `std::endl`
    /// supplies that). Equivalent to `printf("%s %.1f%%", glyph, pct)`.
    #[must_use]
    #[allow(clippy::inherent_to_string)]
    pub fn str(&self) -> String {
        format!("{} {}%", self.frame(), cfmt::fixed_f32(self.percent(), 1))
    }
}

impl std::fmt::Display for CyclicProgress {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn frame_table_bytes_match_the_binary_string_table() {
        let expected: [[u8; 3]; 8] = [
            [0xE2, 0xA3, 0xBE],
            [0xE2, 0xA3, 0xBD],
            [0xE2, 0xA3, 0xBB],
            [0xE2, 0xA2, 0xBF],
            [0xE2, 0xA1, 0xBF],
            [0xE2, 0xA3, 0x9F],
            [0xE2, 0xA3, 0xAF],
            [0xE2, 0xA3, 0xB7],
        ];
        for (i, want) in expected.iter().enumerate() {
            assert_eq!(FRAMES[i].as_bytes(), want, "frame {i}");
            assert_eq!(FRAMES[i].len(), 3, "frame {i} must be 3 bytes");
        }
    }

    #[test]
    fn program_lines_one_through_three() {
        let mut c1 = CyclicProgress::new(5);
        let mut c2 = CyclicProgress::new(10);
        let mut c3 = CyclicProgress::new(15);
        for _ in 0..3 {
            c1.next();
        }
        for _ in 0..6 {
            c2.next();
        }
        for _ in 0..9 {
            c3.next();
        }
        assert_eq!(c1.str(), "\u{28BF} 60.0%");
        assert_eq!(c2.str(), "\u{28EF} 60.0%");
        assert_eq!(c3.str(), "\u{28FD} 60.0%");
        assert_eq!(c1.str().as_bytes()[..3], [0xE2, 0xA2, 0xBF]);
    }

    #[test]
    fn starts_at_zero_and_does_not_validate_total() {
        assert_eq!(CyclicProgress::new(5).count(), 0);
        assert_eq!(CyclicProgress::new(0).count(), 0);
        assert_eq!(CyclicProgress::new(-5).total(), -5);
        assert_eq!(CyclicProgress::new(5).str(), "\u{28FE} 0.0%");
    }

    #[test]
    fn next_wraps_modulo_total_and_never_reaches_one_hundred_percent() {
        let mut c = CyclicProgress::new(5);
        let mut seen = Vec::new();
        for _ in 0..12 {
            c.next();
            seen.push(c.count());
        }
        assert_eq!(seen, vec![1, 2, 3, 4, 0, 1, 2, 3, 4, 0, 1, 2]);

        // The best a total of 5 can ever report is 80.0%.
        let mut c = CyclicProgress::new(5);
        for _ in 0..4 {
            c.next();
        }
        assert_eq!(c.str(), "\u{287F} 80.0%");
        c.next();
        assert_eq!(c.str(), "\u{28FE} 0.0%");
    }

    #[test]
    fn negative_total_cycles_like_its_absolute_value() {
        let mut neg = CyclicProgress::new(-5);
        let mut pos = CyclicProgress::new(5);
        for _ in 0..12 {
            neg.next();
            pos.next();
            assert_eq!(neg.count(), pos.count());
        }
        let mut c = CyclicProgress::new(-5);
        for _ in 0..3 {
            c.next();
        }
        assert_eq!(c.str(), "\u{28BF} -60.0%");
    }

    #[test]
    fn total_of_one_never_advances() {
        let mut c = CyclicProgress::new(1);
        for _ in 0..5 {
            c.next();
            assert_eq!(c.count(), 0);
        }
        assert_eq!(c.str(), "\u{28FE} 0.0%");
    }

    #[test]
    fn total_zero_without_next_reports_negative_nan() {
        // 0.0f / 0.0f is the x86 default QNaN (sign bit set) -> glibc "-nan".
        assert_eq!(CyclicProgress::new(0).str(), "\u{28FE} -nan%");
    }

    #[test]
    fn frame_index_uses_unsigned_remainder() {
        // count == -1 must select frame 7, never panic on a negative index.
        for (count, want) in [(-1i32, 7usize), (-2, 6), (-8, 0), (-9, 7), (i32::MIN, 0)] {
            let c = CyclicProgress { count, total: 8 };
            assert_eq!(c.frame(), FRAMES[want], "count {count}");
        }
    }

    #[test]
    fn percentage_is_computed_in_single_precision() {
        // f32 arithmetic gives 28.8; f64 would give 28.7.
        let c = CyclicProgress { count: 23, total: 80 };
        assert_eq!(c.str(), "\u{28F7} 28.8%");
        for (count, total, want) in [(47, 80, "58.7"), (49, 80, "61.2"), (51, 80, "63.8")] {
            let c = CyclicProgress { count, total };
            assert!(c.str().ends_with(&format!(" {want}%")), "{count}/{total}");
        }
    }

    #[test]
    fn display_impl_agrees_with_str() {
        let mut c = CyclicProgress::new(15);
        for _ in 0..9 {
            c.next();
        }
        assert_eq!(c.to_string(), c.str());
    }
}

//! [`ProgressDisplay`] -- a `Progress: p% (current/total)` line.

use super::cfmt;

/// The literal prefix of every rendered line (`"Progress: "`, 10 bytes).
const PREFIX: &str = "Progress: ";
/// The literal between the percentage and the counts (`"% ("`, 3 bytes).
const MID: &str = "% (";
/// The literal between the two counts (`"/"`, 1 byte).
const SEP: &str = "/";
/// The literal that closes the line (`")"`, 1 byte).
const SUFFIX: &str = ")";

/// A simple `current`-of-`total` progress readout.
///
/// C++ layout: `sizeof == 8`, `int current` at offset 0 and `int total` at
/// offset 4 -- proven by `main` walking an array of three with a stride of 8,
/// and by `display()` reading only `[rbx]` and `[rbx+4]`.
///
/// Nothing here clamps: `update` and `increment` assign and add verbatim,
/// `total` is never touched after construction, and `display` contains no
/// comparison against `total` at all. `current` may legitimately exceed
/// `total` (`150.0% (150/100)`) or go negative (`-10.0% (-10/100)`).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ProgressDisplay {
    /// C++ `current`, object offset 0: the numerator, and the field
    /// [`increment`](Self::increment) mutates.
    current: i32,
    /// C++ `total`, object offset 4: the denominator. Never mutated after
    /// construction.
    total: i32,
}

impl Default for ProgressDisplay {
    /// C++: `ProgressDisplay displays[3];` default-constructs the array, which
    /// requires a defaulted `total`. This is the one **unobservable** choice in
    /// the port: the compiler dead-stored the default construction away
    /// entirely (`main` jumps straight to writing the folded constants), and
    /// the program overwrites all three slots before reading any of them.
    ///
    /// `total = 100` is used because the header demonstrably relies on default
    /// arguments elsewhere (`Format::percision`'s `precision = 1` is
    /// materialised at the call site), `ProgressDisplay(int total = 100)` is
    /// the one-liner that makes the array declaration compile, and it keeps a
    /// fresh object well-defined (`Progress: 0.0% (0/100)`) instead of
    /// producing `Progress: -nan% (0/0)`.
    fn default() -> Self {
        Self {
            current: 0,
            total: 100,
        }
    }
}

impl ProgressDisplay {
    /// C++: `explicit ProgressDisplay(int total)`. `current` starts at 0 and
    /// `total` is stored without validation.
    #[must_use]
    pub const fn new(total: i32) -> Self {
        Self { current: 0, total }
    }

    /// C++: `void update(int current)` -- a plain assignment, no clamping.
    pub fn update(&mut self, current: i32) {
        self.current = current;
    }

    /// C++: `void increment(int amount)` -- `current += amount`, `total`
    /// untouched, no clamping.
    ///
    /// `wrapping_add` mirrors the plain `add` instruction the C++ compiles to,
    /// so an overflow wraps rather than panicking in debug builds. Unreachable
    /// here: the largest `current` this program ever holds is 170.
    pub fn increment(&mut self, amount: i32) {
        self.current = self.current.wrapping_add(amount);
    }

    /// The current value. C++ `current`.
    #[must_use]
    pub const fn current(&self) -> i32 {
        self.current
    }

    /// The configured total. C++ `total`.
    #[must_use]
    pub const fn total(&self) -> i32 {
        self.total
    }

    /// C++: `(static_cast<float>(current) / total) * 100.0f`.
    ///
    /// The division happens **first** and everything stays in single precision
    /// (`cvtsi2ss`, `cvtsi2ss`, `divss`, `mulss 100.0f`). This is not
    /// interchangeable with `current * 100 / total`: the two disagree on 2977
    /// of the pairs with `total <= 20000`, for instance `47/80` renders as
    /// `58.7` here and `58.8` the other way round.
    #[must_use]
    pub fn percent(&self) -> f32 {
        (self.current as f32) / (self.total as f32) * 100.0f32
    }

    /// C++: `std::string display() const`.
    ///
    /// ```text
    /// oss << "Progress: " << std::fixed << std::setprecision(1) << pct
    ///     << "% (" << current << "/" << total << ")";
    /// ```
    ///
    /// One space after the colon, one before the `(`, no trailing space and no
    /// trailing newline -- the caller's `std::endl` supplies that. The counts
    /// go through `operator<<(int)`: plain signed decimal, no width, no
    /// padding, no `+` sign.
    #[must_use]
    pub fn display(&self) -> String {
        let pct = cfmt::fixed_f32(self.percent(), 1);
        format!(
            "{PREFIX}{pct}{MID}{current}{SEP}{total}{SUFFIX}",
            current = self.current,
            total = self.total,
        )
    }
}

impl std::fmt::Display for ProgressDisplay {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.display())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn program_lines_four_through_nine() {
        let mut displays: [ProgressDisplay; 3] = Default::default();
        displays[0] = ProgressDisplay::new(50);
        displays[1] = ProgressDisplay::new(100);
        displays[2] = ProgressDisplay::new(200);
        displays[0].update(25);
        displays[1].update(75);
        displays[2].update(150);
        assert_eq!(displays[0].display(), "Progress: 50.0% (25/50)");
        assert_eq!(displays[1].display(), "Progress: 75.0% (75/100)");
        assert_eq!(displays[2].display(), "Progress: 75.0% (150/200)");

        displays[0].increment(5);
        displays[1].increment(10);
        displays[2].increment(20);
        assert_eq!(displays[0].display(), "Progress: 60.0% (30/50)");
        assert_eq!(displays[1].display(), "Progress: 85.0% (85/100)");
        assert_eq!(displays[2].display(), "Progress: 85.0% (170/200)");
    }

    #[test]
    fn literal_fragments_are_exact() {
        assert_eq!(PREFIX.len(), 10);
        assert_eq!(MID.len(), 3);
        assert_eq!(SEP.len(), 1);
        assert_eq!(SUFFIX.len(), 1);
        let s = ProgressDisplay::new(50).display();
        assert!(s.starts_with("Progress: "));
        assert!(s.ends_with(')'));
        assert!(!s.contains('\n'));
    }

    #[test]
    fn new_starts_at_zero_and_default_is_zero_of_one_hundred() {
        assert_eq!(ProgressDisplay::new(50).current(), 0);
        let d = ProgressDisplay::default();
        assert_eq!((d.current(), d.total()), (0, 100));
        assert_eq!(d.display(), "Progress: 0.0% (0/100)");
    }

    #[test]
    fn total_is_never_mutated() {
        let mut d = ProgressDisplay::new(200);
        d.update(150);
        d.increment(20);
        assert_eq!(d.total(), 200);
        assert_eq!(d.current(), 170);
    }

    #[test]
    fn nothing_is_clamped() {
        let mut d = ProgressDisplay::new(100);
        d.update(150);
        assert_eq!(d.display(), "Progress: 150.0% (150/100)");
        d.update(-10);
        assert_eq!(d.display(), "Progress: -10.0% (-10/100)");
        let mut d = ProgressDisplay::new(7);
        d.update(22);
        assert_eq!(d.display(), "Progress: 314.3% (22/7)");
    }

    #[test]
    fn division_happens_first_in_single_precision() {
        // `current * 100 / total` would print 58.8 for this pair.
        let mut d = ProgressDisplay::new(80);
        d.update(47);
        assert_eq!(d.display(), "Progress: 58.7% (47/80)");
        // Exact binary tie: 13/400*100 == 3.25 -> ties-to-even -> 3.2.
        let mut d = ProgressDisplay::new(400);
        d.update(13);
        assert_eq!(d.display(), "Progress: 3.2% (13/400)");
    }

    #[test]
    fn zero_total_yields_nan_or_infinity_rather_than_a_panic() {
        assert_eq!(ProgressDisplay::new(0).display(), "Progress: -nan% (0/0)");
        let mut d = ProgressDisplay::new(0);
        d.update(5);
        assert_eq!(d.display(), "Progress: inf% (5/0)");
        d.update(-5);
        assert_eq!(d.display(), "Progress: -inf% (-5/0)");
    }

    #[test]
    fn negative_total_flips_the_sign_and_preserves_negative_zero() {
        let mut d = ProgressDisplay::new(-3);
        d.update(420);
        assert_eq!(d.display(), "Progress: -14000.0% (420/-3)");
        // 0 / -3 is -0.0f and must keep its sign.
        d.update(0);
        assert_eq!(d.display(), "Progress: -0.0% (0/-3)");
        let mut d = ProgressDisplay::new(-2);
        d.update(-1);
        assert_eq!(d.display(), "Progress: 50.0% (-1/-2)");
    }

    #[test]
    fn extreme_magnitudes_keep_single_precision_rounding() {
        let mut d = ProgressDisplay::new(1);
        d.update(i32::MAX);
        assert_eq!(
            d.display(),
            "Progress: 214748364800.0% (2147483647/1)"
        );
        let mut d = ProgressDisplay::new(i32::MAX);
        d.update(1);
        assert_eq!(d.display(), "Progress: 0.0% (1/2147483647)");
    }

    #[test]
    fn increment_wraps_instead_of_panicking() {
        let mut d = ProgressDisplay::new(100);
        d.update(i32::MAX);
        d.increment(1);
        assert_eq!(d.current(), i32::MIN);
    }

    #[test]
    fn display_impl_agrees_with_display_method() {
        let mut d = ProgressDisplay::new(50);
        d.update(25);
        assert_eq!(d.to_string(), d.display());
    }
}

//! [`Format`] -- the two stateless string helpers.

use super::cfmt;

/// The precision C++ supplies when the caller omits it:
/// `static std::string percentage(float value, int precision = 1);`
///
/// Only one `percentage` symbol exists in the binary (there is no one-argument
/// overload), and the three call sites materialise `1`, `2` and `3` in `esi`
/// immediately before the call -- the signature of a default argument.
pub const DEFAULT_PRECISION: i32 = 1;

/// The `%` suffix appended by [`Format::percentage`] (1 byte).
const PERCENT: &str = "%";
/// The separator used by [`Format::progress`] (1 byte).
const SLASH: &str = "/";

/// C++: `namespace indicators { struct Format { /* only statics */ }; }`
///
/// A stateless namespace of formatting helpers. Each function builds a fresh
/// `std::ostringstream`, so no stream state leaks between calls and both are
/// pure and reentrant.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct Format;

impl Format {
    /// C++: `Format::percentage(value)` -- the defaulted-precision form.
    ///
    /// Equivalent to `percentage_with(value, 1)`. Rust has no default
    /// arguments, so the C++ default is modelled as this second entry point
    /// rather than being folded into the caller.
    #[must_use]
    pub fn percentage(value: f32) -> String {
        Self::percentage_with(value, DEFAULT_PRECISION)
    }

    /// C++: `static std::string percentage(float value, int precision = 1)`,
    /// i.e. `oss << std::fixed << std::setprecision(precision)
    ///           << (value * 100.0f) << "%"`.
    ///
    /// `value` is a **fraction**: `0.25` renders as `"25.0%"`. It is never
    /// clamped or validated -- `1.5` gives `"150.0%"` and `-0.25` gives
    /// `"-25.0%"`.
    ///
    /// # Why the parameter is `f32`
    ///
    /// The `* 100` is a single-precision `mulss` against the 4-byte constant
    /// `100.0f`; the result is only widened with `cvtss2sd` for the stream.
    /// Taking `f64` (or multiplying in `f64`) changes the digits for a majority
    /// of inputs -- `percentage_with(0.1275, 1)` is `"12.8%"` here because the
    /// `f32` product is exactly `12.75`, but `"12.7%"` if the multiply happens
    /// in `f64`. It also lets huge inputs overflow to `"inf%"` exactly as the
    /// original does.
    ///
    /// No width or fill is ever set on the stream, so the result is never
    /// padded and never uses scientific notation. A negative `precision` means
    /// six decimals; see [`cfmt::fixed`].
    #[must_use]
    pub fn percentage_with(value: f32, precision: i32) -> String {
        let scaled: f32 = value * 100.0f32;
        format!("{}{PERCENT}", cfmt::fixed_f32(scaled, precision))
    }

    /// C++: `static std::string progress(int current, int total)`, i.e.
    /// `oss << current << "/" << total`.
    ///
    /// Two `operator<<(int)` calls around a one-byte literal: no percentage, no
    /// division (so `total == 0` is perfectly safe), no padding and no sign
    /// forcing. The parameters are `i32` rather than an unsigned type so that
    /// negatives round-trip: `progress(-5, 100)` is `"-5/100"`.
    #[must_use]
    pub fn progress(current: i32, total: i32) -> String {
        format!("{current}{SLASH}{total}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn program_lines_ten_through_fifteen() {
        assert_eq!(Format::percentage(0.25f32), "25.0%");
        assert_eq!(Format::percentage_with(0.5f32, 2), "50.00%");
        assert_eq!(Format::percentage_with(0.75f32, 3), "75.000%");
        assert_eq!(Format::progress(25, 100), "25/100");
        assert_eq!(Format::progress(50, 100), "50/100");
        assert_eq!(Format::progress(75, 100), "75/100");
    }

    #[test]
    fn default_precision_is_one() {
        assert_eq!(DEFAULT_PRECISION, 1);
        assert_eq!(
            Format::percentage(0.25f32),
            Format::percentage_with(0.25f32, 1)
        );
    }

    #[test]
    fn precision_zero_omits_the_radix_point() {
        assert_eq!(Format::percentage_with(0.25f32, 0), "25%");
        assert_eq!(Format::percentage_with(2.0f32, 0), "200%");
        assert_eq!(Format::percentage_with(0.0001f32, 0), "0%");
    }

    #[test]
    fn negative_precision_means_six_decimals() {
        assert_eq!(Format::percentage_with(0.25f32, -1), "25.000000%");
        assert_eq!(Format::percentage_with(0.25f32, -3), "25.000000%");
        assert_eq!(Format::percentage_with(0.1f32, 6), "10.000000%");
    }

    #[test]
    fn values_outside_zero_to_one_are_not_clamped() {
        assert_eq!(Format::percentage(1.5f32), "150.0%");
        assert_eq!(Format::percentage(-0.25f32), "-25.0%");
        assert_eq!(Format::percentage(-0.0f32), "-0.0%");
    }

    #[test]
    fn the_multiply_is_single_precision() {
        // f32: 0.1275 * 100 == exactly 12.75 -> ties-to-even -> 12.8.
        // f64 would give 12.749999761581421 -> 12.7.
        assert_eq!(Format::percentage_with(0.1275f32, 1), "12.8%");
        assert_eq!(
            Format::percentage_with(f32::from_bits(0x3e00_092d), 3),
            "12.503%"
        );
        // 0.2f32 * 100.0f32 is exactly 20.0; an f64 multiply would expose
        // 20.000000298023223876953125 at high precision.
        assert_eq!(
            Format::percentage_with(0.2f32, 20),
            "20.00000000000000000000%"
        );
        // FLT_MAX overflows the f32 multiply -- a third proof it is not f64.
        assert_eq!(Format::percentage_with(f32::MAX, 2), "inf%");
    }

    #[test]
    fn ties_round_half_to_even() {
        assert_eq!(Format::percentage_with(0.005f32, 0), "0%");
        assert_eq!(Format::percentage_with(0.015f32, 0), "2%");
        assert_eq!(Format::percentage_with(0.025f32, 0), "2%");
        assert_eq!(Format::percentage_with(0.035f32, 0), "4%");
        assert_eq!(Format::percentage_with(0.045f32, 0), "4%");
    }

    #[test]
    fn non_finite_values_use_the_glibc_spellings() {
        assert_eq!(Format::percentage(f32::INFINITY), "inf%");
        assert_eq!(Format::percentage(f32::NEG_INFINITY), "-inf%");
        assert_eq!(Format::percentage(f32::from_bits(0x7fc0_0000)), "nan%");
        assert_eq!(Format::percentage(f32::from_bits(0xffc0_0000)), "-nan%");
    }

    #[test]
    fn progress_needs_no_guards() {
        assert_eq!(Format::progress(0, 0), "0/0");
        assert_eq!(Format::progress(7, 0), "7/0");
        assert_eq!(Format::progress(-5, 100), "-5/100");
        assert_eq!(
            Format::progress(i32::MIN, i32::MAX),
            "-2147483648/2147483647"
        );
    }

    #[test]
    fn nothing_is_padded_or_newline_terminated() {
        for s in [
            Format::percentage(0.25f32),
            Format::percentage_with(0.5f32, 2),
            Format::progress(25, 100),
        ] {
            assert_eq!(s.trim(), s);
            assert!(!s.contains('\n'));
        }
    }
}

